import {TurnInput} from './turn-input.mjs';
import {ENEMY_TYPES} from './enemies.mjs';
import {Game,BIOMES,EQUIPMENT,UPGRADES,ELEMENTS,ROOM_TYPES,normalizeMeta,talentCost,VERSION} from './engine.mjs';
import {Renderer} from './render.mjs';
import {Sound} from './audio.mjs';
import {FeverShow} from './fever-show.mjs';
import {FeverGame} from './fever.mjs';
import {feverCard,feverPause,feverGuide,feverResult,feverHud} from './fever-ui.mjs';
const $=id=>document.getElementById(id),keys={meta:'drill-delve-meta-v1',run:'drill-delve-run-v3',migration:'drill-delve-v3-migrated',sound:'drill-delve-sound-v1',clock:'drill-delve-clock-v1',play:'relic-delve-play-mode-v1',feverRun:'relic-delve-fever-run-v1',feverBest:'relic-delve-fever-best-v1'};
function read(key){try{return JSON.parse(localStorage.getItem(key));}catch{return null;}}
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{return false;}}
function erase(key){try{localStorage.removeItem(key);}catch{}}
let meta=normalizeMeta(read(keys.meta)),game=new Game(2177,meta),home=true,modalMode='',guideBack='home',saved=read(keys.run)||(!read(keys.migration)?read('drill-delve-run-v2'):null),storageWarned=false;
const canvas=$('game'),ctx=canvas.getContext('2d',{alpha:false}),renderer=new Renderer(ctx),sound=new Sound();sound.enabled=read(keys.sound)!==false;
const feverShow=new FeverShow({reducedMotion:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches??false});
let preferredPlay=read(keys.play)==='fever'?'fever':'expedition',savedFever=read(keys.feverRun),steerQueued=null,startQueued=null;
const rawRecord=read(keys.feverBest),feverRecord={score:Math.max(0,Number(rawRecord?.score)||0),combo:Math.max(0,Number(rawRecord?.combo)||0),runs:Math.max(0,Number(rawRecord?.runs)||0)};
const isFever=()=>game.arcade==='fever';
const pointers=new Map(),keyboard=new Map(),turnInput=new TurnInput();let preferredClock=read(keys.clock)==='turn'?'turn':'realtime',order=0,healQueued=false,pulseQueued=false,lastHud=0,last=0,accumulator=0,saveDue=0;
const fmt=n=>Math.floor(n).toLocaleString('ja-JP');
function svg(id){return `<svg aria-hidden="true"><use href="#i-${id}"/></svg>`;}
function clearInput(){steerQueued=null;startQueued=null;pointers.clear();keyboard.clear();turnInput.clear();healQueued=false;pulseQueued=false;document.querySelectorAll('.held').forEach(n=>n.classList.remove('held'));}
function save(){saveDue=0;if(home||['dead','win','fever-result'].includes(game.mode))return;const data=game.serialize(),key=isFever()?keys.feverRun:keys.run,ok=write(key,data);if(isFever()){if(ok)savedFever=data;}else{if(ok)saved=data;write(keys.meta,meta);}if(!ok&&!storageWarned){storageWarned=true;game.toast('保存できません。このまま遊び続けられます。');}}
function show(content,kind=''){clearInput();$('overlay').hidden=false;$('overlay').className='overlay scrollable '+kind;$('overlay').innerHTML=`<div class="modal-card">${content}</div>`;$('overlay').scrollTop=0;}
function hide(){clearInput();$('overlay').hidden=true;$('overlay').innerHTML='';}
function setStatus(text){$('status').textContent=text;}
function clockPicker(mode,forNew=false){return `<div class="clock-picker"><small>${forNew?'新しい探索のモード':'探索モード'}</small><div role="group" aria-label="探索モード">${[['realtime','リアルタイム'],['turn','ターン制']].map(([id,label])=>`<button data-clock="${id}" aria-pressed="${mode===id}" class="${mode===id?'selected':''}">${label}</button>`).join('')}</div><p>${mode==='turn'?'操作したときだけ時間が進む。危険時は長押し停止。指を離して次の1手。':'掘り進みながら、動く敵と落盤をかわす。'}</p></div>`;}
function modePicker(){return `<div class="mode-picker" role="group" aria-label="遊ぶモード"><button data-mode="expedition" class="${preferredPlay==='expedition'?'selected':''}" aria-pressed="${preferredPlay==='expedition'}">遺跡の探索<small>ROGUELITE</small></button><button data-mode="fever" class="${preferredPlay==='fever'?'selected':''}" aria-pressed="${preferredPlay==='fever'}">採掘フィーバー<small>NEW · 90秒・死亡なし</small></button></div>`;}
function expeditionCard(){return `${clockPicker(preferredClock,true)}${saved?'<button class="primary" data-action="continue">掘削をつづける <span>↗</span></button><button class="secondary" data-action="new-confirm">新しい探索へ</button>':'<button class="primary" data-action="new">地層へ潜る <span>↗</span></button>'}<button class="text-button" data-action="guide">${svg('book')}遊び方・フィールドガイド</button>`;}
function homeView(){home=true;modalMode='home';clearInput();const talents=[['hull','♥','強化外殻','HP +8'],['air','◈','結晶容量','各属性 +3'],['drill','✦','破砕腕強化','攻撃 +2']];
  show(`<div class="home-intro"><p class="eyebrow">${preferredPlay==='fever'?'90 SECOND CASCADE ARCADE':'A CASCADE-MINING ROGUELITE'}</p><h1>${preferredPlay==='fever'?'DIG<br><em>FEVER</em><span class="fever-bang">!</span>':'RELIC<br><em>DELVE</em><span style="color:#f2c17c">.</span>'}</h1><p class="home-jp">${preferredPlay==='fever'?'採掘フィーバー':'崩落の遺跡'}</p><p class="home-copy">${preferredPlay==='fever'?'掘る。砕く。止まらない。<br>連鎖と誘爆で、宝石の大シャワー。<br><b>10秒間の3列フィーバーを狙え！</b>':'掘る。崩れる。連鎖する。<br>足場を読み、一気に深く潜れ。<br><b>6つの遺跡から「星の記憶」を取り戻せ。</b>'}</p><div class="tiny-tags"><span>掘削 × 落下連鎖</span><span>4属性の共鳴</span><span>分岐する18の地層</span></div></div><div class="home-actions button-stack">${modePicker()}${preferredPlay==='fever'?feverCard(feverRecord,savedFever):expeditionCard()}</div><div class="meta-box"><div class="meta-top"><span>BASE CAMP / 永続強化</span><b>◇ ${fmt(meta.cores)}</b></div><div class="talents">${talents.map(([id,icon,name,desc])=>`<button class="talent" data-talent="${id}" ${meta.talents[id]>=5||meta.cores<talentCost(meta.talents[id])?'disabled':''}><span class="talent-icon">${icon}</span><strong>${name} ${meta.talents[id]}/5</strong><small>${desc}</small><span class="cost">${meta.talents[id]>=5?'MAX':`◇ ${talentCost(meta.talents[id])}`}</span></button>`).join('')}</div></div><div class="home-bottom"><span>BEST <b>${fmt(meta.best)}</b> m</span><span>拠点の強化記録は引き継ぎ</span></div>`,preferredPlay==='fever'?'home arcade-home':'home');$('pause').disabled=true;hud(true);$('theme-color').setAttribute('content',preferredPlay==='fever'?'#e9f4de':'#0c1522');
}
function start(seed=Date.now()){preferredPlay='expedition';write(keys.play,preferredPlay);write(keys.migration,true);game=new Game(seed,meta,preferredClock);home=false;modalMode='play';hide();sound.unlock();$('pause').disabled=false;accumulator=0;renderer.lastStage=-1;save();hud(true);setStatus(game.turnBased?'ターン制。方向で移動・掘削、待つは1タップ1手。危険時は長押し停止。指を離して次の1手。':'下を掘って地底へ。頭上の塊が揺れたら落盤に注意。');}
function startFever(seed=Date.now()){if(!home)save();preferredPlay='fever';write(keys.play,preferredPlay);game=new FeverGame(seed);home=false;modalMode='play';hide();sound.unlock();$('pause').disabled=false;accumulator=0;renderer.lastStage=-1;save();hud(true);setStatus('採掘フィーバー。左右かGOで開始。下へ自動掘削、小ボタンで爆破。');}
function continueFever(){try{game=FeverGame.restore(savedFever);preferredPlay='fever';write(keys.play,preferredPlay);home=false;modalMode='play';hide();sound.unlock();$('pause').disabled=false;accumulator=0;renderer.lastStage=-1;save();hud(true);}catch{erase(keys.feverRun);savedFever=null;startFever();game.toast('記録を読み込めなかったため、新しい90秒を開始します');}}
function continueRun(){preferredPlay='expedition';write(keys.play,preferredPlay);try{game=Game.restore(saved,meta);write(keys.migration,true);home=false;modalMode='';hide();$('pause').disabled=false;sound.unlock();renderer.lastStage=-1;accumulator=0;game.toast('掘削を再開 / '+ROOM_TYPES[game.roomType].goal);save();syncModal();hud(true);}catch{erase(keys.run);saved=null;start();game.toast('記録を読み込めなかったため、新しい探索を開始しました。');}}
function pause(){if(home||!['play','pause'].includes(game.mode))return;game.mode='pause';save();modalMode='pause';if(isFever()){show(feverPause(game));hud(true);return;}show(`<p class="eyebrow">THE EXPLORER'S REST</p><h2>ひとやすみ。</h2>${clockPicker(game.clockMode)}<p class="pause-stats">${game.biome.name} · 地層 ${game.roomNumber}/18 · LV ${game.player.level}<br>${ROOM_TYPES[game.roomType].goal} (${game.goal.progress}%)<br>遺跡の時間は止まっています。探索は自動保存されます。</p><div class="equip"><small>CURRENT EQUIPMENT</small><h3>${game.drill.name} / ${game.suit.name}</h3><p>攻撃力 ${Math.round(game.power)} · 術式威力 ×${game.magic.toFixed(2)} · シールド ${game.player.shield}</p></div><div class="pack-list">${Object.entries(game.player.upgrades).map(([id,n])=>`<span>${UPGRADES.find(x=>x.id===id)?.name||id} ×${n}</span>`).join('')||'<span>強化はレベルアップで獲得</span>'}</div><div class="button-stack"><button class="primary" data-action="resume">遺跡にもどる</button><button class="secondary" data-action="guide">フィールドガイド</button><button class="text-button" data-action="home">保存して拠点へ</button></div>`);}
function resume(){if(game.mode==='pause'){game.mode='play';if(!game.turnBased&&!isFever())game.player.invuln=Math.max(.7,game.player.invuln);}modalMode='play';hide();sound.unlock();accumulator=0;}
function guide(){guideBack=home?'home':game.mode==='pause'?'pause':game.mode;if(!home&&game.mode==='play'){pause();guideBack='pause';}modalMode='guide';
  if(home?preferredPlay==='fever':isFever()){show(feverGuide());return;}
  const items=[['◷','ターン制で、時間を手にする','タイトルかポーズでターン制を選択。方向タップ1回で移動・掘削・攻撃を1手。「待つ」は1タップ1手で、その場のまま敵と落盤を進める。方向は長押しで連続操作できるが、近くの敵・攻撃予告・落盤・被弾を確認すると停止する。指を離して、次の1手を選ぼう。方向と大ボタンを同時に押した場合は方向が優先される。被弾やシールド消費のあとは2手の間、追加ダメージを受けない。共鳴・回復も1手、属性選択・ガイド・進めない壁への入力は消費なし。操作しなければ、敵・落盤・崩落・クールダウンは進まない。装備や強化の速さは攻撃力に換算される。'],['▼','掘ると、足場が崩れて落ちる','十字キーの下を長押しして掘削。空いた場所には重力で落ちる。左右で進路を変え、上で1マスだけ小ジャンプ。右の「掘る」長押しで高速掘削。'],['◈','まとまりを掘り、着地で連鎖','同色の鉱脈はつながった分だけ一気に砕ける。支えを失った塊は揺れてから落下。着地で同色が4個以上つながると追加の連鎖が起きる。'],['↘','岩を押し、狙って落とす','丸い岩の隣で左右入力すると1マス押せる。押す先は空けておこう。薄い点線と枠は現在の地形から見た落下見込み。支えを掘り、敵の群れに落として一掃しよう。上下からは岩を掘削でき、押せないときも削れる。'],['↷','敵の攻撃を誘い、回り込む','通常敵の×マスは次の攻撃先。横へ避けるか掘削で中断し、空振り後のOPENを狙おう。突進は敵と岩壁を巻き込み、胞子弾も敵や爆薬に当たる。落石の仕掛け・誘爆の間・回り込みの間では、岩や横道を使って攻略を変えよう。'],['❄','地形の強化で作戦を変える','震地の楔：2マス以上落ちた塊の着地で左右へ衝撃波。氷棺の印：凍った敵や、凍結撃破で残る氷塊を横から押し、盾や足場に使う。氷塊はターン制で8手、リアルタイムで8秒残る。鉱脈の余韻：鉱石8個以上の連鎖で次の共鳴が広域化。出口の3択で獲得できる。'],['↔','頭上を読み、横へ逃げる','落下する塊の下には橙の予告。掘る順番を変えれば落とす場所も変わる。地層には6〜8体の群れ。光る亀裂からは羽虫や特殊な魔物の増援が現れる。落盤や範囲共鳴でまとめて倒そう。大きな連鎖のあとほど、頭上に注意しよう。'],['◎','共鳴で掘り方を変える','上の4色タブで属性を選択し、小さい共鳴ボタンで発動。翠命は回復と崩落減速、熾火は前方爆破、霜晶は落盤凍結、紫電は鉱脈と敵への連鎖雷。結晶不足時は小パルスになる。'],['»','迫る崩落より深く潜る','崩落は上から追いかけてくる。寄り道するか、連鎖の多い道を急ぐかを選ぼう。地層の底のゲートに入ると安全な休憩所へ。'],['✦','成長は、掘る流れを止めない','経験値でレベルアップ。強化の3択と装備比較は地層の出口でまとめて行う。次に潜る鉱脈を選び、ビルドを育てよう。']];
  show(`<p class="eyebrow">CASCADE MINING GUIDE</p><h2>掘る、落ちる、つなげる。</h2><div class="guide-content">${items.map(([icon,title,body])=>`<div class="guide-item"><span class="guide-icon">${icon}</span><div><b>${title}</b><p>${body}</p></div></div>`).join('')}</div><h3>遺跡の魔物と対処法</h3><div class="guide-content">${Object.values(ENEMY_TYPES).map(e=>`<div class="guide-item"><span class="guide-icon"><canvas data-foe="${Object.keys(ENEMY_TYPES).find(k=>ENEMY_TYPES[k]===e)}" width="84" height="84" style="width:32px;height:32px" aria-hidden="true"></canvas></span><div><b>${e.name}</b><p>${e.desc}</p></div></div>`).join('')}</div><div class="guide-foot">PC：方向キー / WASDで移動・掘削、Spaceで高速掘削（ターン制は待機、. / 5キーでも待機）、1〜4で属性、Xで共鳴、Cで回復、Escで一時停止。<br>途中記録と拠点の強化はこのブラウザーに自動保存。</div><button class="primary" data-action="guide-back">もどる</button>`);
  document.querySelectorAll('[data-foe]').forEach(canvas=>{const context=canvas.getContext('2d'),preview=new Renderer(context);preview.cell=62;context.translate(11,7);const sample=game.makeEnemy(0,0,canvas.dataset.foe,()=>.5);preview.enemy(sample,{player:{x:0,y:-2},biome:game.biome});});

}
function syncModal(){if(home||game.mode===modalMode||modalMode==='guide')return;modalMode=game.mode;const p=game.player;if(game.mode==='play'){hide();return;}save();
  if(isFever()&&game.mode==='fever-result'){const newBest=game.fever.score>feverRecord.score;feverRecord.score=Math.max(feverRecord.score,game.fever.score);feverRecord.combo=Math.max(feverRecord.combo,game.fever.maxCombo);feverRecord.runs++;write(keys.feverBest,feverRecord);erase(keys.feverRun);savedFever=null;show(feverResult(game,feverRecord,newBest),'fever-results');setStatus('採掘フィーバー終了。スコア '+fmt(game.fever.score));return;}
  if(game.mode==='level')show(`<p class="eyebrow">LEVEL ${p.level} / YOUR BUILD</p><h2>次の切り札を、選ぶ。</h2><p class="modal-sub">今回の探索で使う強化を1つ選んでください。</p><div class="choice-list">${game.choice.map((u,i)=>`<button class="choice" data-upgrade="${u.id}"><span class="choice-icon">${u.icon}</span><span class="choice-text"><small>0${i+1} / ${u.kind}</small><b>${u.name}</b><p>${u.desc}</p></span><span class="choice-arrow">↗</span></button>`).join('')}</div><p class="hint-line">同じ強化を選ぶと効果が重なります。選択中は時間停止。</p>`);
  if(game.mode==='loot'){const {slot,item}=game.loot,old=slot==='drills'?game.drill:game.suit;show(`<p class="eyebrow">ANCIENT EQUIPMENT</p><h2>遺跡からの贈り物。</h2><p class="modal-sub">新たな装備で探索を変えるか、売って次の備えにするか。</p><div class="equipment-compare"><div class="equip"><small>現在の装備</small><h3>${old.name}</h3><p>${old.desc}</p></div><div class="equip new"><small>NEW EQUIPMENT</small><h3>${item.name}</h3><p>${item.desc}</p></div></div><div class="button-stack"><button class="primary" data-action="equip">新しい装備に交換</button><button class="secondary" data-action="sell">交換せず20Gで売却</button></div>`);}
  if(game.mode==='route')show(`<p class="eyebrow">LAYER CLEARED / ${game.stats.rooms} OF 18</p><h2>${game.routeOptions[0]==='boss'?'守護者が、待っている。':'次の遺跡へ、道が分かれる。'}</h2><p class="modal-sub">地層の目的を達成。HP5回復・全属性3補充・12G獲得。</p><div class="route-list">${game.routeOptions.map(id=>{const r=ROOM_TYPES[id];return `<button class="choice" data-route="${id}"><span class="choice-icon">${r.icon}</span><span class="choice-text"><small>NEXT STRATUM</small><b>${r.name}</b><p>${r.hint}</p></span><span class="choice-arrow">↗</span></button>`;}).join('')}</div><p class="hint-line">探索の途中記録は自動保存されます。</p>`);
  if(game.mode==='camp')campView();
  if(['dead','win'].includes(game.mode)){meta=normalizeMeta(game.meta);write(keys.meta,meta);erase(keys.run);saved=null;const win=game.mode==='win';show(`<p class="eyebrow">${win?'THE ARCHIVE IS AWAKENED':'ANOTHER PATH REMAINS'}</p><h2>${win?'星の記憶が、目を覚ます。':'切り拓いた道は、消えない。'}</h2><p class="modal-sub">${win?'18の地層と3体の守護者を越え、古代の遺跡を解放しました。':game.reason+'。持ち帰ったコアで、次の探索を強化しよう。'}</p><div class="stat-grid"><div class="stat-cell"><small>攻略した地層</small><strong>${game.stats.rooms}</strong><span>/ 18</span></div><div class="stat-cell"><small>落下連鎖</small><strong>${game.stats.cascades}</strong></div><div class="stat-cell"><small>最大鉱脈連鎖</small><strong>${game.stats.maxChain}</strong></div><div class="stat-cell"><small>最終レベル</small><strong>${p.level}</strong><span>LV</span></div></div><div class="reward"><span>持ち帰った深層コア</span><b>◇ +${game.reward}</b></div><div class="button-stack"><button class="primary" data-action="home">拠点で次の探索を準備</button><button class="secondary" data-action="new">もう一度、遺跡へ</button></div>`);setStatus(win?'星の記憶を解放しました。':'探索終了。'+game.reason);}
}
function campView(){const next=BIOMES[game.stage+1];show(`<p class="eyebrow">RUIN ${game.stage+1} COMPLETE / SAFE HAVEN</p><h2>遺跡の焚き火</h2><p class="modal-sub">HP20・全属性6を回復。次は「${next.name}」。<br>${next.hazard} <b style="color:var(--gold)">所持 ${fmt(game.player.gold)} G</b></p><div class="shop-list">${game.shopStock.map(it=>`<button class="shop-item" data-buy="${it.id}" ${it.bought||game.player.gold<it.cost?'disabled':''}><span class="shop-info"><b>${it.name}</b><small>${it.desc}</small></span><strong>${it.bought?'購入済':it.cost+' G'}</strong></button>`).join('')}</div><button class="primary" data-action="next">第${game.stage+2}遺跡へ <span>↗</span></button><p class="hint-line">購入せずに進めます。拠点の永続強化は探索終了後。</p>`);}
function hud(force=false){if(!force&&performance.now()-lastHud<80)return;lastHud=performance.now();const p=game.player,g=game.goal;
  $('biome-name').textContent=game.biome.name;$('depth').textContent=fmt(game.depth);$('floor-badge').textContent=`${game.roomNumber} / 18`;$('hp-fill').style.width=Math.max(0,p.hp/game.maxHp*100)+'%';$('hp-text').textContent=`${Math.ceil(p.hp)} / ${game.maxHp}`;$('goal-fill').style.width=g.progress/g.total*100+'%';$('goal-count').textContent=`地層の深さ ${g.progress}%`;const setup=game.setpieces?.find(a=>Math.abs(p.y-a.y)<=4&&p.y<=a.packY+2),tips={drop:'岩を横から押し、群れの上へ落とそう',blast:'敵の攻撃を爆薬や爆裂ダニへ誘導しよう',flank:'横道から盾の背後へ。回復も回収できる'};$('objective-text').textContent=p.y-game.collapseFront<5?'崩落が接近！ 下へ掘り進もう':p.wideReady?'広域共鳴 準備完了 · 次の共鳴は範囲拡大':setup?tips[setup.type]:ROOM_TYPES[game.roomType].goal;$('level').textContent=p.level;$('xp-fill').style.width=p.xp/p.nextXp*100+'%';$('gold').textContent=fmt(p.gold);$('shield').textContent=p.shield;$('potions').textContent=p.potions;$('heal').disabled=!p.potions||p.hp>=game.maxHp;$('drill-name').textContent=game.drill.name;
  $('pulse-text').textContent=p.pulseTimer>0?(game.turnBased?Math.ceil(p.pulseTimer)+'T':p.pulseTimer.toFixed(1)+'s'):p.charges[p.element]>=game.castCost?ELEMENTS[p.element].short:'パルス';$('pulse').classList.toggle('cooling',p.pulseTimer>0);$('pulse').classList.toggle('wide-ready',!!p.wideReady);$('pulse-cooldown').style.height=p.pulseTimer/8*100+'%';$('sound').classList.toggle('muted',!sound.enabled);$('sound').setAttribute('aria-pressed',String(sound.enabled));
  for(const el of ELEMENTS){const button=$('element-'+el.id);button.classList.toggle('selected',p.element===el.id);button.setAttribute('aria-pressed',String(p.element===el.id));button.querySelector('b').textContent=Math.floor(p.charges[el.id]);button.querySelector('i').style.width=p.charges[el.id]/p.chargeMax*100+'%';}
  const el=ELEMENTS[p.element];$('cast-name').textContent=game.turnBased?'待つ':'掘る';$('cast-cost').textContent=game.turnBased?'1タップ1手':'長押しで高速';$('rush').setAttribute('aria-label',game.turnBased?'待機 1タップで1ターン進める':'高速掘削 長押し');$('rush-icon').setAttribute('href',game.turnBased?'#i-wait':'#i-drill');$('clock-status').hidden=home||!game.turnBased;$('clock-status').textContent=`TURN ${fmt(game.turnCount)} · ${turnInput.suspended?'指を離して次の1手':'入力待ち'}${Math.ceil(p.invuln)>1?' · 保護'+(Math.ceil(p.invuln)-1)+'手':''}`;$('game-shell').classList.toggle('turn-mode',!home&&game.turnBased);$('rush').style.setProperty('--element-color','#edc18a');$('rush').classList.remove('empty');$('pulse').style.color=el.color;
  const boss=game.boss,visible=boss&&!home&&Math.abs(boss.y-p.y)<9;$('boss-hud').hidden=!visible;if(visible){$('boss-name').textContent=boss.id+(boss.state==='open'?' · 核露出':boss.state==='warn'?' · 光る列を回避':' · 外殻 '+(3-(boss.phase||0)));$('boss-percent').textContent=Math.max(0,Math.ceil(boss.hp/boss.maxHp*100))+'%';$('boss-fill').style.width=Math.max(0,boss.hp/boss.maxHp*100)+'%';}
  $('pulse').setAttribute('aria-label','選択した属性の共鳴を使う');feverHud($,game,feverRecord,home);
}
function input(){let dir=null,rush=false,max=-1;for(const v of [...keyboard.values(),...pointers.values()]){if(v.dir&&v.order>max){dir=v.dir;max=v.order;}if(v.rush)rush=true;}const out={dir,rush,pulse:pulseQueued,heal:healQueued,tap:steerQueued?.dir,start:!!startQueued};steerQueued=null;startQueued=null;pulseQueued=false;healQueued=false;return out;}
$('elements').addEventListener('click',e=>{const button=e.target.closest('[data-element]');if(!button||home)return;game.player.element=Number(button.dataset.element);sound.unlock();sound.play('click');hud(true);});
const dpad=$('dpad');
function padDirection(e){const rect=dpad.getBoundingClientRect(),dx=e.clientX-(rect.left+rect.width/2),dy=e.clientY-(rect.top+rect.height/2);if(isFever())return dx<-8?'left':dx>8?'right':null;if(Math.hypot(dx,dy)<10)return null;return Math.abs(dx)>Math.abs(dy)?dx<0?'left':'right':dy<0?'up':'down';}
function highlight(){document.querySelectorAll('.dir').forEach(n=>n.classList.toggle('held',[...pointers.values(),...keyboard.values()].some(v=>v.dir===n.dataset.dir)));$('rush').classList.toggle('held',[...pointers.values(),...keyboard.values()].some(v=>v.rush));}
dpad.addEventListener('pointerdown',e=>{if(home||game.mode!=='play')return;e.preventDefault();const dir=e.target.closest('[data-dir]')?.dataset.dir||padDirection(e);if(!dir||isFever()&&!['left','right'].includes(dir))return;sound.unlock();dpad.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{dir,order:++order});if(isFever())steerQueued={id:'p:'+e.pointerId,dir};if(game.turnBased)turnInput.press('p:'+e.pointerId,{dir},performance.now());highlight();});
dpad.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;e.preventDefault();const dir=padDirection(e);pointers.set(e.pointerId,{dir,order:++order});if(game.turnBased){if(dir)turnInput.press('p:'+e.pointerId,{dir},performance.now());else turnInput.release('p:'+e.pointerId);}highlight();});
for(const type of ['pointerup','pointercancel','lostpointercapture'])dpad.addEventListener(type,e=>{if(type==='pointercancel'&&steerQueued?.id==='p:'+e.pointerId)steerQueued=null;if(type==='pointercancel'&&startQueued==='p:'+e.pointerId)startQueued=null;pointers.delete(e.pointerId);turnInput.release('p:'+e.pointerId,type==='pointercancel');highlight();});
$('rush').addEventListener('pointerdown',e=>{if(home||game.mode!=='play')return;e.preventDefault();sound.unlock();$('rush').setPointerCapture(e.pointerId);pointers.set(e.pointerId,{rush:true,order:++order});if(isFever()&&!game.started)startQueued='p:'+e.pointerId;if(game.turnBased)turnInput.press('p:'+e.pointerId,{wait:true},performance.now());highlight();});
for(const type of ['pointerup','pointercancel','lostpointercapture'])$('rush').addEventListener(type,e=>{if(type==='pointercancel'&&steerQueued?.id==='p:'+e.pointerId)steerQueued=null;if(type==='pointercancel'&&startQueued==='p:'+e.pointerId)startQueued=null;pointers.delete(e.pointerId);turnInput.release('p:'+e.pointerId,type==='pointercancel');highlight();});
$('pulse').addEventListener('click',()=>{if(!home&&game.mode==='play'){sound.unlock();if(game.turnBased)turnInput.enqueue({pulse:true});else pulseQueued=true;}});
$('heal').addEventListener('click',()=>{if(!home&&game.mode==='play'){sound.unlock();if(game.turnBased)turnInput.enqueue({heal:true});else healQueued=true;}});
$('pause').addEventListener('click',()=>{sound.unlock();if(game.mode==='pause')resume();else pause();});
$('sound').addEventListener('click',()=>{sound.toggle();write(keys.sound,sound.enabled);hud(true);});
$('guide-side').addEventListener('click',guide);
const dirKeys={ArrowUp:'up',KeyW:'up',ArrowDown:'down',KeyS:'down',ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right'};
window.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey)return;if(e.code==='Escape'){e.preventDefault();if(modalMode==='guide')handleAction('guide-back');else if(game.mode==='pause')resume();else pause();return;}if(e.code==='Enter'&&home&&modalMode==='home'){e.preventDefault();if(preferredPlay==='fever'){if(savedFever)continueFever();else startFever();}else if(saved)continueRun();else start();return;}
  if(home||game.mode!=='play')return;const dir=dirKeys[e.code];if(dir||['Space','KeyX','KeyC','Period','Numpad5','Digit5'].includes(e.code))e.preventDefault();if(e.repeat)return;sound.unlock();if(dir){keyboard.set(e.code,{dir,order:++order});if(isFever())steerQueued={id:'k:'+e.code,dir};if(game.turnBased)turnInput.press('k:'+e.code,{dir},performance.now());}if(e.code==='Space'){keyboard.set(e.code,{rush:true,order:++order});if(isFever()&&!game.started)startQueued='k:'+e.code;if(game.turnBased)turnInput.press('k:'+e.code,{wait:true},performance.now());}if(game.turnBased&&['Period','Numpad5','Digit5'].includes(e.code))turnInput.press('k:'+e.code,{wait:true},performance.now());if(['Digit1','Digit2','Digit3','Digit4'].includes(e.code)){game.player.element=Number(e.code.slice(-1))-1;hud(true);}if(e.code==='KeyX'){if(game.turnBased)turnInput.enqueue({pulse:true});else pulseQueued=true;}if(e.code==='KeyC'){if(game.turnBased)turnInput.enqueue({heal:true});else healQueued=true;}highlight();});
window.addEventListener('keyup',e=>{keyboard.delete(e.code);turnInput.release('k:'+e.code);highlight();});
window.addEventListener('blur',()=>{clearInput();if(!home&&game.mode==='play')pause();});
document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInput();if(!home&&game.mode==='play')pause();save();}});
window.addEventListener('pagehide',()=>{clearInput();save();});
document.addEventListener('contextmenu',e=>{if(e.target.closest('.play-shell'))e.preventDefault();});
function handleAction(action){sound.unlock();sound.play('click');
  if(action==='fever-new'){startFever();return;}if(action==='fever-retry'){startFever(game.seed);return;}if(action==='fever-continue'){continueFever();return;}if(action==='fever-new-confirm'){show(`<p class="eyebrow">NEW FEVER RUN</p><h2>新しい90秒をはじめる</h2><p class="modal-sub">途中のフィーバー記録を上書きします。ハイスコアは残ります。</p><div class="button-stack"><button class="primary fever-primary" data-action="fever-new">新しい90秒へ</button><button class="secondary" data-action="home">もどる</button></div>`);return;}
  if(action==='new'){start();return;}if(action==='continue'){continueRun();return;}if(action==='new-confirm'){show(`<p class="eyebrow">NEW EXPEDITION</p><h2>新しい探掘をはじめる</h2><p class="modal-sub">途中の探索記録を上書きします。拠点の永続強化と持ち帰ったコアは引き継がれます。</p><div class="button-stack"><button class="primary" data-action="new">新しく潜る</button><button class="secondary" data-action="home">もどる</button></div>`);return;}
  if(action==='home'){if(!home)save();homeView();return;}if(action==='resume'){resume();return;}if(action==='guide'){guide();return;}
  if(action==='guide-back'){modalMode='';if(guideBack==='home')homeView();else if(guideBack==='pause'){game.mode='play';pause();}else syncModal();return;}
  if(action==='equip'||action==='sell'){game.takeEquipment(action==='equip');modalMode='';syncModal();save();return;}
  if(action==='next'){game.nextFloor();modalMode='';renderer.lastStage=-1;syncModal();save();return;}
}
$('overlay').addEventListener('click',e=>{const button=e.target.closest('button');if(!button||button.disabled)return;
  if(button.dataset.mode){preferredPlay=button.dataset.mode==='fever'?'fever':'expedition';write(keys.play,preferredPlay);homeView();return;}
  if(button.dataset.clock){preferredClock=button.dataset.clock==='turn'?'turn':'realtime';write(keys.clock,preferredClock);clearInput();accumulator=0;if(home)homeView();else if(game.mode==='pause'){game.setClockMode(preferredClock);pause();hud(true);}return;}
  if(button.dataset.action)handleAction(button.dataset.action);
  if(button.dataset.route){game.chooseRoute(button.dataset.route);modalMode='';renderer.lastStage=-1;syncModal();save();}
  if(button.dataset.upgrade){game.chooseUpgrade(button.dataset.upgrade);modalMode='';syncModal();save();}
  if(button.dataset.buy){game.buy(button.dataset.buy);campView();hud(true);save();}
  if(button.dataset.talent){const id=button.dataset.talent,cost=talentCost(meta.talents[id]);if(meta.cores>=cost&&meta.talents[id]<5){meta.cores-=cost;meta.talents[id]++;write(keys.meta,meta);sound.play('upgrade');homeView();}}
});
function resize(){const r=$('viewport').getBoundingClientRect();if(r.width<=0||r.height<=0)return;const dpr=Math.min(2,window.devicePixelRatio||1);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);renderer.resize(r.width,r.height);}
new ResizeObserver(resize).observe($('viewport'));window.addEventListener('resize',()=>{clearInput();resize();});
function frame(now){
  const dt=last?Math.min(.1,(now-last)/1000):1/60;last=now;
  if(!home){
    if(game.turnBased){
      accumulator=0;const action=turnInput.next(now);
      if(action&&game.takeTurn(action)){
        if(game.turnDanger||game.events.some(e=>['hurt','guard'].includes(e.type)))turnInput.suspend();
        hud(true);
      }game.step(dt);
    }else{accumulator+=dt;while(accumulator>=1/60){const controls=input();game.step(1/60,controls);if(isFever())feverShow.drive(game,controls.rush);accumulator-=1/60;}}
    for(const cue of feverShow.update(game))sound.play(cue.type,cue);
    for(const event of game.events.splice(0)){
      for(const cue of feverShow.receive(game,event))sound.play(cue.type,cue);
      if(event.type==='save'){if(game.turnBased)saveDue=now+250;else save();}
      else sound.play(event.type,event);
    }
    if(saveDue&&now>=saveDue)save();syncModal();
  }else accumulator=0;
  renderer.draw(game,dt,home,feverShow);
  const fxActive=!home&&isFever();$('fever-combo').style.setProperty('--combo-pop',fxActive&&feverShow.comboBeat>game.time?'1.06':'1');$('game-shell').classList.toggle('fever-paused',fxActive&&game.mode!=='play');
  sound.update(!home&&game.mode==='play'&&(!isFever()||game.started),game.stage,isFever()?{arcade:true,fever:game.fever.active>0,boost:feverShow.juice?.boost}:null);hud();requestAnimationFrame(frame);
}
if(saved){try{Game.restore(saved,meta);}catch{saved=null;erase(keys.run);}}
if(savedFever){try{FeverGame.restore(savedFever);}catch{savedFever=null;erase(keys.feverRun);}}
resize();homeView();requestAnimationFrame(frame);
if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(r=>r.update()).catch(()=>{});
window.addEventListener('error',e=>{setStatus('エラーが発生しました。再読み込みで途中の記録から再開できます。');console.error(e.error);});
